float noise3_lq (float2 uvi) { float n1,n2,n3;
  uvi = uvi + time*.001;
  n1 = tex2D(sampler_noise_lq, (uvi)).r;
  n2 = tex2D(sampler_noise_lq, (uvi*2)).r;
  n3 = tex2D(sampler_noise_lq, (uvi*4)).r;
  return n1 + n2/2 + n3/4 - .875;} 

float alti (float x0, float z0)
{return q10*z0*(sin(x0*q11 + q13*z0)) * sin(z0*q12+q13) + pow(x0,2)*q14
